<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { platformApi, statusText } from '../api'
import ModalDialog from '../components/ModalDialog.vue'
import PageState from '../components/PageState.vue'
import FilterSelect from '../components/FilterSelect.vue'
const items=ref<any[]>([]);const loading=ref(false);const saving=ref(false);const error=ref('');const notice=ref('');const modal=ref(false);const current=ref<any>(null);const form=reactive({module_type:'menu',code:'',name:'',path:'',permission_code:'',sort_no:0,status:'active',is_admin_only:false})
async function load(){loading.value=true;error.value='';try{items.value=(await platformApi<{items:any[]}>('/modules')).items}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function open(item:any){current.value=item||null;Object.assign(form,item?{module_type:item.module_type,code:item.code,name:item.name,path:item.path,permission_code:item.permission_code,sort_no:item.sort_no,status:item.status,is_admin_only:item.is_admin_only}:{module_type:'menu',code:'',name:'',path:'',permission_code:'',sort_no:0,status:'active',is_admin_only:false});modal.value=true}
async function save(){saving.value=true;error.value='';try{const payload={...form,path:form.path||null};if(current.value)await platformApi(`/modules/${current.value.id}`,{method:'PATCH',body:JSON.stringify(payload)});else await platformApi('/modules',{method:'POST',body:JSON.stringify(payload)});modal.value=false;notice.value='功能模块已保存';await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
onMounted(load)
</script>
<template><div style="max-width:1400px;margin:auto;padding:28px"><div class="page-header"><div><h1>平台功能模块定义</h1><p>统一维护菜单、按钮和权限点，供所有租户角色分配</p></div><div class="header-actions"><RouterLink to="/platform/tenants" class="button secondary">返回平台控制面</RouterLink><button class="button" @click="open(null)">+ 新增模块</button></div></div><div v-if="error" class="notice error">{{error}}</div><div v-if="notice" class="notice success">{{notice}}</div><section class="panel"><PageState :loading="loading"/><div v-if="!loading" class="table-wrap"><table><thead><tr><th>排序</th><th>类型</th><th>模块编码</th><th>名称</th><th>权限点</th><th>路径</th><th>管理员专用</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items"><td>{{item.sort_no}}</td><td>{{item.module_type}}</td><td>{{item.code}}</td><td>{{item.name}}</td><td>{{item.permission_code}}</td><td>{{item.path||'—'}}</td><td>{{item.is_admin_only?'是':'否'}}</td><td><span class="status" :class="item.status">{{statusText[item.status]}}</span></td><td><button class="button link" @click="open(item)">编辑</button></td></tr></tbody></table><PageState :empty="!items.length"/></div></section></div><ModalDialog v-if="modal" :title="current?'编辑功能模块':'新增功能模块'" @close="modal=false"><div class="form-grid"><div class="field"><label>类型</label><FilterSelect v-model="form.module_type" :options="[{value:'menu',label:'菜单'},{value:'button',label:'按钮'},{value:'api',label:'API'}]"/></div><div class="field"><label>排序</label><input v-model.number="form.sort_no" type="number"></div><div class="field"><label>模块编码</label><input v-model.trim="form.code" :disabled="!!current" placeholder="menu.example"></div><div class="field"><label>模块名称</label><input v-model.trim="form.name"></div><div class="field"><label>权限点</label><input v-model.trim="form.permission_code" :disabled="!!current" placeholder="resource:action"></div><div class="field"><label>路径</label><input v-model.trim="form.path"></div><div class="field"><label>状态</label><FilterSelect v-model="form.status" :options="[{value:'active',label:'启用'},{value:'disabled',label:'停用'}]"/></div><div class="field"><label>管理员专用</label><label><input v-model="form.is_admin_only" type="checkbox"> 不允许分配给自定义角色</label></div></div><template #footer><button class="button secondary" @click="modal=false">取消</button><button class="button" :disabled="saving" @click="save">保存</button></template></ModalDialog></template>
